//! HTML entity handling.
//!
//! Port of FreshRSS's `html_only_entity_decode()` (`lib/lib_rss.php`). A syndication parser has
//! already resolved the five XML entities; what is left over are the *HTML-only* names —
//! `&eacute;`, `&mdash;`, `&nbsp;` — which appear constantly in RSS that was generated by string
//! concatenation rather than a real serializer. Those need decoding, but `&lt;` must survive:
//! turning it into `<` would resurrect markup that the feed author escaped on purpose.
//!
//! PHP implements this as a `strtr` over `array_diff(HTML_ENTITIES, HTML_SPECIALCHARS)`, which
//! means it only ever sees *named* references. This port matches that: `&#233;` is left alone, on
//! the reasoning that a conforming XML parse has already resolved it, and a second pass would only
//! fire on double-encoded text where decoding is damage.

/// The entities this module refuses to decode.
///
/// `&quot;` and `&apos;` are included because PHP's table is built with `ENT_NOQUOTES`, which
/// excludes both quotes; preserving them is what makes that exclusion observable.
const XML_ENTITIES: [&str; 5] = ["&amp;", "&lt;", "&gt;", "&quot;", "&apos;"];

/// Decodes HTML named entities while leaving the XML five intact.
///
/// Returns the input unchanged (as a borrowed `Cow`) when there is nothing to do, which is the
/// common case — most feed text contains no entities at all after the XML parse.
pub fn html_only_entity_decode(text: &str) -> std::borrow::Cow<'_, str> {
    if !text.contains('&') {
        return std::borrow::Cow::Borrowed(text);
    }

    let bytes = text.as_bytes();
    let mut out = String::with_capacity(text.len());
    let mut cursor = 0;
    let mut decoded_any = false;

    while let Some(rel) = bytes[cursor..].iter().position(|&b| b == b'&') {
        let amp = cursor + rel;
        let Some(name) = entity_name(&bytes[amp..]) else {
            // A bare `&` or a numeric reference: copy through untouched.
            out.push_str(&text[cursor..=amp]);
            cursor = amp + 1;
            continue;
        };
        // `semi` is the index of the closing `;`, so the entity is `text[amp..=semi]`.
        let semi = amp + 1 + name.len();
        let whole = &text[amp..=semi];

        if XML_ENTITIES.contains(&whole) {
            out.push_str(&text[cursor..=semi]);
        } else {
            out.push_str(&text[cursor..amp]);
            out.push_str(&html_escape::decode_html_entities(whole));
            decoded_any = true;
        }
        cursor = semi + 1;
    }

    out.push_str(&text[cursor..]);
    if decoded_any {
        std::borrow::Cow::Owned(out)
    } else {
        std::borrow::Cow::Borrowed(text)
    }
}

/// Reads `&name` and returns the byte span of `name`, or `None` if this is not a named reference.
///
/// HTML5 names are alphanumeric (`&NotNestedGreaterGreater;`), so anything else — a `#` for a
/// numeric reference, a space, an immediate `;` — means "not an entity".
fn entity_name(bytes: &[u8]) -> Option<&[u8]> {
    let rest = bytes.get(1..)?;
    let len = rest
        .iter()
        .position(|&b| !b.is_ascii_alphanumeric())
        .unwrap_or(rest.len());
    if len == 0 || rest.get(len) != Some(&b';') {
        return None;
    }
    Some(&rest[..len])
}

/// Resolves the five XML entities and numeric character references, and leaves everything else
/// verbatim.
///
/// This is deliberately *not* `quick_xml::escape::unescape`, which errors on an unrecognized name.
/// Real feeds carry HTML-only entities (`&eacute;`) inside XML text, and that is a parse failure to
/// a strict unescaper. Here it is passed through untouched so [`html_only_entity_decode`] — which
/// knows the HTML table — can resolve it one step later. Being total is the point: a single odd
/// entity must never cost us a whole article body.
pub fn xml_unescape(text: &str) -> std::borrow::Cow<'_, str> {
    if !text.contains('&') {
        return std::borrow::Cow::Borrowed(text);
    }

    let mut out = String::with_capacity(text.len());
    let mut rest = text;
    let mut resolved_any = false;

    while let Some(amp) = rest.find('&') {
        out.push_str(&rest[..amp]);
        let after = &rest[amp + 1..];

        // A reference must terminate with `;` before any whitespace or `<`, per XML.
        let semi = after
            .find(';')
            .filter(|end| !after[..*end].bytes().any(|b| b.is_ascii_whitespace() || b == b'<'));

        match semi {
            Some(0) => {
                // `&;` is not a reference.
                out.push('&');
                rest = after;
            }
            Some(end) => {
                let body = &after[..end];
                match resolve_xml_reference(body) {
                    Some(value) => {
                        out.push_str(&value);
                        resolved_any = true;
                    }
                    // An HTML-only name: leave `&eacute;` exactly as it was.
                    None => {
                        out.push('&');
                        out.push_str(body);
                        out.push(';');
                    }
                }
                rest = &after[end + 1..];
            }
            None => {
                out.push('&');
                rest = after;
            }
        }
    }

    out.push_str(rest);
    if resolved_any {
        std::borrow::Cow::Owned(out)
    } else {
        std::borrow::Cow::Borrowed(text)
    }
}

/// Resolves one XML reference body (the part between `&` and `;`).
fn resolve_xml_reference(body: &str) -> Option<String> {
    match body {
        "amp" => return Some("&".into()),
        "lt" => return Some("<".into()),
        "gt" => return Some(">".into()),
        "quot" => return Some("\"".into()),
        "apos" => return Some("'".into()),
        _ => {}
    }
    let digits = body.strip_prefix('#')?;
    let code = match digits.strip_prefix(['x', 'X']) {
        Some(hex) => u32::from_str_radix(hex, 16).ok()?,
        None => digits.parse::<u32>().ok()?,
    };
    // `char::from_u32` already rejects surrogates and anything past U+10FFFF, which XML also does.
    char::from_u32(code).map(|c| c.to_string())
}

/// Escapes the five XML specials, for the places that need to emit text into markup.
///
/// Note this is the *inverse* of [`html_only_entity_decode`] only for those five; the HTML-only
/// names have no single canonical escape and are left as literal UTF-8, which is what this project
/// stores.
pub fn encode_specials(text: &str) -> std::borrow::Cow<'_, str> {
    if !text.bytes().any(|b| matches!(b, b'&' | b'<' | b'>' | b'"' | b'\'')) {
        return std::borrow::Cow::Borrowed(text);
    }
    let mut out = String::with_capacity(text.len() + 8);
    for ch in text.chars() {
        match ch {
            '&' => out.push_str("&amp;"),
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            '"' => out.push_str("&quot;"),
            '\'' => out.push_str("&#39;"),
            _ => out.push(ch),
        }
    }
    std::borrow::Cow::Owned(out)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn decodes_html_only_names() {
        assert_eq!(
            html_only_entity_decode("Caf&eacute; &mdash; d&eacute;j&agrave; vu"),
            "Café — déjà vu"
        );
    }

    #[test]
    fn preserves_the_xml_five() {
        let input = "&lt;b&gt;bold&lt;/b&gt; &amp; &quot;quoted&quot; &apos;single&apos;";
        assert_eq!(html_only_entity_decode(input), input);
    }

    #[test]
    fn preserves_numeric_references_like_php_does() {
        // A conforming XML parse already resolved these; decoding again would damage
        // double-encoded text such as `&amp;#8212;` → `&#8212;`.
        assert_eq!(html_only_entity_decode("&#8212; &#233;"), "&#8212; &#233;");
    }

    #[test]
    fn leaves_a_bare_ampersand_alone() {
        assert_eq!(html_only_entity_decode("Tom & Jerry & friends"), "Tom & Jerry & friends");
        assert_eq!(html_only_entity_decode("a & b"), "a & b");
    }

    #[test]
    fn does_not_decode_an_unterminated_name() {
        // No trailing `;`, so this is prose, not an entity. PHP's `strtr` agrees.
        assert_eq!(html_only_entity_decode("&eacute without semicolon"), "&eacute without semicolon");
    }

    #[test]
    fn borrows_when_there_is_nothing_to_decode() {
        let text = String::from("plain text with &amp; an xml entity");
        let out = html_only_entity_decode(&text);
        assert!(matches!(out, std::borrow::Cow::Borrowed(_)));
        assert!(std::ptr::eq(out.as_ptr(), text.as_ptr()));
    }

    #[test]
    fn handles_html5_only_names() {
        assert_eq!(html_only_entity_decode("&CounterClockwiseContourIntegral;"), "∳");
        assert_eq!(html_only_entity_decode("&NewLine;"), "\n");
    }

    #[test]
    fn mixed_content_decodes_only_the_html_part() {
        assert_eq!(
            html_only_entity_decode("&lt;p&gt;Caf&eacute;&lt;/p&gt;"),
            "&lt;p&gt;Café&lt;/p&gt;"
        );
    }

    #[test]
    fn encode_specials_is_the_inverse_for_the_five() {
        for name in XML_ENTITIES {
            let decoded = html_only_entity_decode(name);
            assert_eq!(decoded, name, "{name} is preserved");
        }
        assert_eq!(encode_specials("<&>\"'"), "&lt;&amp;&gt;&quot;&#39;");
        assert!(matches!(encode_specials("plain"), std::borrow::Cow::Borrowed(_)));
    }

    #[test]
    fn empty_and_amp_only_inputs() {
        assert_eq!(html_only_entity_decode(""), "");
        assert_eq!(html_only_entity_decode("&"), "&");
        assert_eq!(html_only_entity_decode("&&&&"), "&&&&");
    }

    // --- xml_unescape ------------------------------------------------------

    #[test]
    fn resolves_the_five_predefined_entities() {
        assert_eq!(xml_unescape("&amp;&lt;&gt;&quot;&apos;"), "&<>\"'");
        assert_eq!(xml_unescape("a &lt; b &amp;&amp; c &gt; d"), "a < b && c > d");
    }

    #[test]
    fn resolves_numeric_references_in_both_bases() {
        assert_eq!(xml_unescape("&#233;&#x65;&#XE9;"), "éeé");
        assert_eq!(xml_unescape("&#8212;"), "\u{2014}");
        assert_eq!(xml_unescape("&#10;"), "\n");
    }

    #[test]
    fn leaves_html_only_names_for_the_next_pass() {
        // This is the whole reason the function exists: a strict unescaper errors here.
        assert_eq!(xml_unescape("Caf&eacute; &mdash; x"), "Caf&eacute; &mdash; x");
        assert_eq!(
            html_only_entity_decode(&xml_unescape("&lt;b&gt;Caf&eacute;&lt;/b&gt;")),
            "<b>Café</b>"
        );
    }

    #[test]
    fn invalid_references_are_left_verbatim() {
        assert_eq!(xml_unescape("&;"), "&;");
        assert_eq!(xml_unescape("&#;"), "&#;");
        assert_eq!(xml_unescape("&#xZZ;"), "&#xZZ;");
        // A surrogate has no character representation.
        assert_eq!(xml_unescape("&#xD800;"), "&#xD800;");
        // Beyond the Unicode range.
        assert_eq!(xml_unescape("&#x110000;"), "&#x110000;");
        // An unterminated reference stops being a reference at whitespace.
        assert_eq!(xml_unescape("&amp here;"), "&amp here;");
        assert_eq!(xml_unescape("&lt;p&gt;;"), "<p>;");
    }

    #[test]
    fn a_bare_ampersand_survives() {
        assert_eq!(xml_unescape("Tom & Jerry"), "Tom & Jerry");
        assert_eq!(xml_unescape("a & b & c"), "a & b & c");
        assert_eq!(xml_unescape("&"), "&");
    }

    #[test]
    fn borrows_when_there_is_nothing_to_resolve() {
        let text = String::from("Caf&eacute; and a bare & sign");
        let out = xml_unescape(&text);
        assert!(matches!(out, std::borrow::Cow::Borrowed(_)));
        assert!(std::ptr::eq(out.as_ptr(), text.as_ptr()));
    }

    #[test]
    fn resolution_is_not_recursive() {
        // `&amp;lt;` must become the text `&lt;`, not `<`. XML forbids recursive expansion and a
        // feed that wants to display an entity reference depends on it.
        assert_eq!(xml_unescape("&amp;lt;"), "&lt;");
        assert_eq!(xml_unescape("&amp;amp;"), "&amp;");
    }
}
